export const getGetOfficialScheduleUrl = (params: GetOfficialScheduleParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/public-schedules/monsey-trails?${stringifiedParams}` : `/api/public-schedules/monsey-trails`
}

